body.script:
var AP=(function(){
var FALLBACK='https://images.unsplash.com/photo-1578632767115-351597cf2477?q=80&w=600&auto=format&fit=crop';
var POSTS=[];
function esc(s){return String(s||'').replace(/&/g,'&').replace(//g,'>').replace(/"/g,'"');}
function isDirect(s){return /\.(mp4|webm)(\?|#|$)/i.test(s||'');}
function normImg(u){if(!u)return FALLBACK;var s=String(u).trim();if(s.indexOf('data:')===0||s.indexOf('http')===0)return s;return s;}
function fetchAll(page,acc){
acc=acc||[];
var url='/feeds/posts/default?alt=json&max-results=50'+(page>1?'&start-index='+(page):'');
return fetch(url).then(function(r){return r.json();}).then(function(j){
var entries=(j.feed&&j.feed.entry)||[];
entries.forEach(function(e){
var title=(e.title&&e.title.$t)||'';
var href='#';
(e.link||[]).forEach(function(l){if(l.rel==='alternate')href=l.href;});
var img='';
if(e.media$thumbnail&&e.media$thumbnail.url)img=String(e.media$thumbnail.url).replace(/\/s72(-c)?\//,'/s400/');
var labels=[];
(e.category||[]).forEach(function(c){if(c.term)labels.push(c.term);});
var synopsis='',genres=[],episodes=[],slug='',cover='',subtitle='',updatedAt='';
if(e.content&&e.content.$t){
var tmp=document.createElement('div');
tmp.innerHTML=e.content.$t;
var dataEl=tmp.querySelector('#anima-data');
if(dataEl){try{var d=JSON.parse(dataEl.textContent);
if(d.title)title=d.title;if(d.slug)slug=d.slug;if(d.cover)cover=d.cover;
if(d.synopsis)synopsis=d.synopsis;if(d.genres)genres=d.genres;
if(d.episodes)episodes=d.episodes;if(d.subtitle)subtitle=d.subtitle;
}catch(x){}}
if(!synopsis){synopsis=(tmp.textContent||'').replace(/\s+/g,' ').trim().slice(0,140);}
}
if(e.updated&&e.updated.$t)updatedAt=e.updated.$t;
var ec=episodes.length;
POSTS.push({title:title,slug:slug||title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,''),
href:href,image:normImg(cover||img),subtitle:subtitle||(ec?'Episodio 1':'Nova Postagem'),
genres:genres.length?genres:(labels.length?labels:['Nova']),episodes:episodes,synopsis:synopsis,
labels:labels.length?labels:genres,isNew:updatedAt?(Date.now()-new Date(updatedAt).getTime())<24*3600*1000:false,
updatedAt:updatedAt});
});
var total=j.feed&&j.feed.openSearch$totalFields&&parseInt(j.feed.openSearch$totalFields.$t,10);
if(acc.length+entries.length<total&&entries.length)return fetchAll(page+entries.length,acc.concat(entries));
return acc.concat(entries);
});
}
function cardHTML(a,rank){
var href=a.href||'/';
var g=(a.genres||[]).slice(0,2).join(', ');
var h='';
h+='
';
h+='';
if(a.isNew)h+='NOVO';
if(rank)h+=''+rank+'';
h+='
'+esc(a.title)+'';
h+='
';
h+='
'+esc(a.title)+'';
h+='
'+esc(a.subtitle||'')+'';
if(g)h+=''+esc(g)+'';
h+='';
return h;
}
function loadLatest(posts,perPost,total){
perPost=perPost||6;total=total||18;
var sorted=posts.slice().sort(function(a,b){return(b.updatedAt||'').localeCompare(a.updatedAt||'');});
var lists=[];
sorted.forEach(function(post){
var srcs=post.episodes||[];
if(!srcs.length)return;
var list=[];
for(var i=srcs.length-1;i>=0&&list.length<perPost;i--){
var url='';
if(typeof srcs[i]==='string')url=srcs[i];
else if(srcs[i]&&srcs[i].videos&&srcs[i].videos[0])url=srcs[i].videos[0].url;
if(!url)continue;
list.push({title:'Episodio '+(i+1),subtitle:post.title,image:post.image,genres:post.genres,
isNew:post.isNew,slug:post.slug,href:post.href+'?ep='+(i+1)});
}
if(list.length)lists.push(list);
});
var eps=[];
for(var r=0;eps.length<total;r++){
var added=false;
for(var p=0;p<lists.length;p++){
if(r<lists[p].length&&eps.length<total){eps.push(lists[p][r]);added=true;}
}
if(!added)break;
}
return eps;
}
function renderCarousel(items){
var el=document.getElementById('carousel');
if(!el)return;
el.innerHTML=items.slice(0,18).map(function(a){return cardHTML(a);}).join('');
}
function renderGenreRows(posts){
var box=document.getElementById('genreRows');
if(!box)return;
var sorted=posts.slice().sort(function(a,b){return(b.updatedAt||'').localeCompare(a.updatedAt||'');});
var top10=sorted.slice(0,10);
var html='

Top 10 mais vistosEm alta no site
‹
';
top10.forEach(function(a,i){html+='
'+(i+1)+''+cardHTML(a)+'';});
html+='›';
var allL={};
posts.forEach(function(p){(p.labels||[]).forEach(function(l){allL[l]=1;});});
Object.keys(allL).sort().forEach(function(label){
var items=posts.filter(function(p){return(p.labels||[]).indexOf(label)>=0;});
if(items.length<2)return;
html+='

'+esc(label)+'
';
items.slice(0,12).forEach(function(a){html+=cardHTML(a);});
html+='';
});
box.innerHTML=html;
}
function renderPostLinks(){
var box=document.getElementById('postLinks');
if(!box)return;
var items=POSTS.slice().sort(function(a,b){return(b.updatedAt||'').localeCompare(a.updatedAt||'');});
box.innerHTML=items.length?items.map(function(a){
return'› '+esc(a.title)+'';
}).join(''):'';
}
function renderRec(){
var box=document.getElementById('sideRec');
if(!box)return;
var items=POSTS.slice().sort(function(a,b){return(b.updatedAt||'').localeCompare(a.updatedAt||'');}).slice(0,4);
box.innerHTML=items.length?items.map(function(a){
return''+esc(a.title)+'';
}).join(''):'';
}
function renderGenreFilters(){
var box=document.getElementById('genreFilters');
if(!box)return;
var gs={};
POSTS.forEach(function(p){(p.genres||[]).forEach(function(g){gs[g]=1;});});
box.innerHTML='Todos'+Object.keys(gs).sort().map(function(g){
return''+esc(g)+'';
}).join('');
}
function renderHome(){
var latest=loadLatest(POSTS);
renderCarousel(latest.length?latest:POSTS);
renderGenreRows(POSTS);
renderPostLinks();
renderRec();
renderGenreFilters();
startCarouselAuto();
if(typeof ViewCounter!=='undefined'){try{ViewCounter.incrementSite().then(function(v){
var el=document.getElementById('siteViews');
if(el)el.textContent=Number(v||0).toLocaleString('pt-BR');
});}catch(e){}}
}
function renderPost(d){
var el=document.getElementById('postContent');
if(!el)return;
document.getElementById('homeContent').classList.add('hidden');
el.classList.remove('hidden');
if(!d.episodes||!d.episodes.length){el.innerHTML='
Sem episodios';return;}
var cur=0,srv=0;
function curUrl(){
var ep=d.episodes[cur];
if(!ep)return'';
if(typeof ep==='string')return ep;
var vids=ep.videos||[];
return(vids[srv]&&vids[srv].url)||(vids[0]&&vids[0].url)||'';
}
function paintPlayer(){
var box=document.getElementById('vp');
if(!box)return;
var src=curUrl();
if(!src){box.innerHTML='
Nenhum video';return;}
if(isDirect(src))box.innerHTML='';
else box.innerHTML='';
}
function render(){
var pills=(d.genres||[]).map(function(g){return''+esc(g)+'';}).join('');
var h='‹ Inicio';
h+='
';
if(d.cover)h+='';
h+='

'+esc(d.title)+'
'+pills+'';
if(d.synopsis)h+='
'+esc(d.synopsis)+'';
h+='
Assistir';
h+='
';
var ep=d.episodes[cur];
var vids=(typeof ep==='object'&&ep&&ep.videos)?ep.videos:[];
if(vids.length>1){
h+='
';
vids.forEach(function(v,j){h+=''+esc(v.name||('Servidor '+(j+1)))+'';});
h+='';
}
h+='
';
h+='‹ Inicio';
h+='<button id="btnPrev"'+(cur<=0?' disabled':'')+'>‹ Anterior';
h+=''+esc((typeof ep==='object'&&ep)?ep.title:'')+' · '+(cur+1)+'/'+d.episodes.length+'';
h+='Proximo ›';
h+='';
h+='
Episodios';
h+='
';
d.episodes.forEach(function(e,i){
var n=(typeof e==='object'&&e&&e.videos)?e.videos.length:1;
var label=n>1?(n+' servidores'):'Toque para assistir';
var title=(typeof e==='object'&&e)?(e.title||('Episodio '+(i+1))):('Episodio '+(i+1));
h+='';
h+='
EP '+String(i+1).padStart(2,'0')+'';
h+='

'+esc(title)+'';
h+='
'+esc(label)+'';
h+='▶';
});
h+='';
if(d.slug)h+='Assistir no Anima Play';
el.innerHTML=h;
paintPlayer();
el.querySelectorAll('[data-srv]').forEach(function(btn){
btn.addEventListener('click',function(){
srv=parseInt(this.getAttribute('data-srv'),10);
paintPlayer();
el.querySelectorAll('[data-srv]').forEach(function(b){b.classList.remove('active');});
btn.classList.add('active');
});
});
el.querySelectorAll('[data-ep]').forEach(function(item){
item.addEventListener('click',function(e){
e.preventDefault();
cur=parseInt(this.getAttribute('data-ep'),10);
srv=0;
render();
document.getElementById('vp').scrollIntoView({behavior:'smooth',block:'center'});
});
});
var pv=document.getElementById('btnPrev');
var nx=document.getElementById('btnNext');
if(pv)pv.addEventListener('click',function(){if(cur>0){cur--;srv=0;render();}});
if(nx)nx.addEventListener('click',function(){if(cur=1&&epP<=d.episodes.length){cur=epP-1;render();}}catch(x){}
if(typeof ViewCounter!=='undefined'&&d.slug){try{ViewCounter.increment(d.slug).then(function(v){
var el2=document.getElementById('apViews');if(el2)el2.textContent=v+' visualizacoes';
});}catch(e){}}
}
render();
}
var carouselTimer=null;
function carouselStep(){
var el=document.getElementById('carousel');
if(!el||!el.children.length)return;
var page=el.clientWidth;
if(el.scrollLeft+page>=el.scrollWidth-10)el.scrollTo({left:0,behavior:'smooth'});
else el.scrollBy({left:page,behavior:'smooth'});
}
function startCarouselAuto(){stopCarouselAuto();carouselTimer=setInterval(carouselStep,4000);}
function stopCarouselAuto(){if(carouselTimer){clearInterval(carouselTimer);carouselTimer=null;}}
function boot(){
var q=document.getElementById('searchInput');
if(q)q.addEventListener('keydown',function(e){if(e.key==='Enter'){var v=q.value.trim();if(v)location.href='/search?q='+encodeURIComponent(v);}});
var dataEl=document.getElementById('anima-data');
if(dataEl&&dataEl.textContent.trim().indexOf('{')===0){
try{renderPost(JSON.parse(dataEl.textContent));}catch(x){}
}else{
fetchAll(1).then(function(){renderHome();}).catch(function(){
var cr=document.getElementById('carousel');if(cr)cr.innerHTML='
Erro ao carregar';
});
}
var cel=document.getElementById('carousel');
if(cel){cel.addEventListener('mouseenter',stopCarouselAuto);cel.addEventListener('mouseleave',startCarouselAuto);}
}
if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('DOMContentLoaded',boot);
return{boot:boot};
})();
function scrollCarousel(dir){var el=document.getElementById('carousel');if(el)el.scrollBy({left:dir*el.clientWidth,behavior:'smooth'});}
function scrollRow(btn,dir){var el=btn.parentElement.querySelector('.genre-row-scroll');if(el)el.scrollBy({left:dir*el.clientWidth*0.8,behavior:'smooth'});}
